<?php
namespace Database\Seeders;
use App\Models\{Bus,Route,Schedule,Stop,User}; use Illuminate\Database\Seeder; use Illuminate\Support\Facades\Hash;
class DatabaseSeeder extends Seeder { public function run(): void { $admin=User::create(['name'=>'Admin Dishub','email'=>'admin@dishub.test','password'=>Hash::make('password'),'is_admin'=>true]); $stops=collect([['Terminal Kampung Rambutan','TKR',-6.3097,106.8842],['Pasar Rebo','PRE',-6.3227,106.8571],['Cawang UKI','CWG',-6.2414,106.8739],['Tebet','TBT',-6.2297,106.8562],['Dukuh Atas','DKA',-6.2006,106.8225]])->map(fn($s)=>Stop::create(['name'=>$s[0],'code'=>$s[1],'latitude'=>$s[2],'longitude'=>$s[3],'address'=>'Jakarta','is_active'=>true])); $bus=Bus::create(['name'=>'Trans Kota Harmoni','code'=>'TK-01','corridor_number'=>'1','color'=>'#0f766e','description'=>'Layanan contoh dari Terminal Kampung Rambutan menuju Dukuh Atas.','estimated_minutes'=>45,'is_active'=>true]); $route=Route::create(['bus_id'=>$bus->id,'name'=>'Kampung Rambutan – Dukuh Atas','direction'=>'Pergi']); $route->stops()->sync($stops->values()->mapWithKeys(fn($stop,$i)=>[$stop->id=>['sequence'=>$i+1,'estimated_minutes'=>$i*10]])); Schedule::create(['bus_id'=>$bus->id,'day_type'=>'Setiap Hari','start_time'=>'05:00','end_time'=>'22:00','headway_minutes'=>15]); } }
